contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target) public payable {
        require(target != address(0));

        // observe before
        bool beforeVal = c.allowedBurningAddresses(target); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setAllowedBurningAddresses(target); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after
        bool afterVal = c.allowedBurningAddresses(target); if (__ESBMC_reverted()) return;

        // If reverted, value must be unchanged; if succeeded, value must be true
        assert(reverted ? afterVal == beforeVal : afterVal == true);
    }

    receive() external payable {}
}

