pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(address target) internal {
        vm.assume(target != address(0));
        bool beforeVal;
        try c.allowedBurningAddresses(target) returns (bool __r) { beforeVal = __r; } catch { return; }
        bool reverted;
        try c.setAllowedBurningAddresses(target) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool afterVal;
        try c.allowedBurningAddresses(target) returns (bool __r) { afterVal = __r; } catch { return; }
        assertTrue(reverted ? afterVal == beforeVal : afterVal == true);
    }

    function testFuzz_run(address target) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target);
    }

    receive() external payable {}
}
